const $ = id => document.getElementById(id);
let video = null, quality = 720, activeJob = null, requestVersion = 0;
let inputTimer, pollTimer, infoController;
let history = [];
try {
  document.body.classList.toggle('dark', localStorage.getItem('softload-theme') === 'dark');
  const saved = JSON.parse(localStorage.getItem('softload-history') || '[]');
  if (Array.isArray(saved)) history = saved.filter(x => x && typeof x.id === 'string' && typeof x.title === 'string').slice(0, 30);
} catch {}
$('themeBtn').onclick = () => {
  document.body.classList.toggle('dark');
  try { localStorage.setItem('softload-theme', document.body.classList.contains('dark') ? 'dark' : 'light'); } catch {}
};
function message(text, kind = '') { $('hint').textContent = text; $('hint').className = 'hint ' + kind; }
function show(id, visible) { $(id).classList.toggle('show', visible); }
function fileURL(id) { return '/api/softload?op=file&id=' + encodeURIComponent(id); }
async function api(op, options = {}) {
  const { id, signal, method = 'GET', data } = options;
  const url = '/api/softload?op=' + op + (id ? '&id=' + encodeURIComponent(id) : '');
  const response = await fetch(url, { method, signal, headers: { 'Content-Type': 'application/json', 'X-Softload': '1' }, body: data ? JSON.stringify(data) : undefined });
  const result = await response.json().catch(() => ({ error: 'Respons layanan tidak dapat dibaca.' }));
  if (!response.ok) { const error = new Error(result.error || 'Layanan sedang tidak tersedia.'); error.status = response.status; throw error; }
  return result;
}
function videoId(value) {
  try {
    const u = new URL(value);
    if (!['https:', 'http:'].includes(u.protocol)) return null;
    let id;
    if (u.hostname === 'youtu.be') id = u.pathname.split('/')[1];
    else if (['youtube.com', 'www.youtube.com', 'm.youtube.com'].includes(u.hostname)) {
      if (u.pathname === '/watch') id = u.searchParams.get('v');
      else if (/^\/(shorts|live|embed)\//.test(u.pathname)) id = u.pathname.split('/')[2];
    }
    return /^[\w-]{11}$/.test(id || '') ? id : null;
  } catch { return null; }
}
function renderQuality() {
  $('qrow').replaceChildren(...video.qualities.map(q => {
    const b = document.createElement('button');
    b.className = 'q' + (q.height === quality ? ' active' : '');
    b.textContent = q.height + 'p'; b.setAttribute('aria-pressed', String(q.height === quality));
    b.onclick = () => { quality = q.height; renderQuality(); };
    return b;
  }));
  const selected = video.qualities.find(q => q.height === quality);
  $('sizeVal').textContent = selected?.bytes ? '~ ' + (selected.bytes / 1048576).toFixed(1) + ' MB' : 'Belum diketahui';
  $('downloadBtn').disabled = !selected;
}
async function inspect() {
  const version = ++requestVersion;
  infoController?.abort(); infoController = new AbortController();
  video = null; show('preview', false); show('opts', false); show('done', false);
  const value = $('url').value.trim(), id = videoId(value);
  if (!id) { message(value ? 'Masukkan tautan YouTube yang valid.' : 'Belum ada tautan dimasukkan.', value ? 'err' : ''); return; }
  message('Membaca informasi video...');
  try {
    const result = await api('info', { method: 'POST', data: { url: value }, signal: infoController.signal });
    if (version !== requestVersion) return;
    video = result; quality = result.qualities.find(q => q.height === 720)?.height || result.qualities[0]?.height || 720;
    $('vtitle').textContent = result.title; $('vchannel').textContent = result.channel;
    const seconds = Math.floor(result.duration || 0);
    $('vdur').textContent = Math.floor(seconds / 60) + ':' + String(seconds % 60).padStart(2, '0');
    $('thumb').hidden = false; $('thumb').src = 'https://i.ytimg.com/vi/' + id + '/mqdefault.jpg';
    show('preview', true); show('opts', true); renderQuality(); message('Pilih kualitas atau unduh audio.', 'ok');
  } catch (e) { if (e.name !== 'AbortError' && version === requestVersion) message(e.message, 'err'); }
}
$('url').oninput = () => {
  requestVersion++; infoController?.abort(); video = null; show('opts', false); show('preview', false); show('done', false);
  clearTimeout(inputTimer); inputTimer = setTimeout(inspect, 650);
};
$('url').onkeydown = e => { if (e.key === 'Enter') { clearTimeout(inputTimer); inspect(); } };
$('pasteBtn').onclick = async () => {
  try { $('url').value = await navigator.clipboard.readText(); clearTimeout(inputTimer); inspect(); }
  catch { message('Tempel manual dengan Ctrl+V atau tekan lama pada kolom.', 'err'); $('url').focus(); }
};
$('thumb').onerror = () => { $('thumb').hidden = true; };
function lock(locked) { $('url').disabled = locked; $('pasteBtn').disabled = locked; }
function progress(job) {
  $('progtext').textContent = job.message;
  const known = Number.isFinite(job.progress);
  $('progwrap').classList.toggle('busy', !known);
  $('progpct').textContent = known ? Math.floor(job.progress) + '%' : '';
  $('proginner').style.width = (known ? job.progress : 35) + '%';
}
async function start(format) {
  if (!video || activeJob) return;
  lock(true); show('opts', false); show('done', false); show('progwrap', true);
  $('cancelBtn').disabled = true; progress({ message: 'Menyiapkan unduhan...', progress: null });
  try {
    const job = await api('create', { method: 'POST', data: { url: $('url').value.trim(), format, quality } });
    activeJob = { id: job.id, title: video.title, format, quality };
    $('cancelBtn').disabled = false; poll();
  } catch (e) { lock(false); show('progwrap', false); show('opts', true); message(e.message, 'err'); }
}
async function poll() {
  const current = activeJob; if (!current) return;
  try {
    const job = await api('status', { id: current.id });
    if (activeJob !== current) return;
    progress(job);
    if (job.status === 'ready') {
      show('progwrap', false); show('done', true); lock(false);
      $('done').querySelector('p').textContent = 'File ' + current.format + ' siap. Klik Simpan berkas untuk mengunduh.';
      $('saveFile').href = fileURL(current.id);
      history = [{ ...current, expires: job.expires, date: Date.now() }, ...history.filter(x => x.id !== current.id)].slice(0, 30);
      saveHistory(); activeJob = null; return;
    }
    if (['failed', 'cancelled'].includes(job.status)) {
      activeJob = null; lock(false); show('progwrap', false); show('opts', true); message(job.message, 'err'); return;
    }
    pollTimer = setTimeout(poll, 1500);

    
  } catch (e) {
    if (activeJob !== current) return;
    if (e.status === 404 || e.status === 410) {
      activeJob = null; lock(false); show('progwrap', false); show('opts', true); message(e.message, 'err'); return;
    }
    // Keep the job ID after network failures; cancellation and retries remain possible.
    message(e.message + ' Mencoba memeriksa status kembali...', 'err');
    pollTimer = setTimeout(async () => {
      if (activeJob !== current) return;
      try {
        const job = await api('status', { id: current.id });
        if (['failed', 'cancelled'].includes(job.status)) {
          activeJob = null; lock(false); show('progwrap', false); show('opts', true); message(job.message, 'err');
        } else poll();
      } catch (e) {
        if (e.status === 404 || e.status === 410) {
          activeJob = null; lock(false); show('progwrap', false); show('opts', true); message(e.message, 'err');
        } else poll();
      }
    }, 4000);
  }
}
$('downloadBtn').onclick = () => start('MP4');
$('audioBtn').onclick = () => start('MP3');
$('cancelBtn').onclick = async () => {
  if (!activeJob) return;
  $('cancelBtn').disabled = true;
  try {
    await api('cancel', { method: 'DELETE', id: activeJob.id });
    clearTimeout(pollTimer); activeJob = null; lock(false); show('progwrap', false); show('opts', true); message('Proses dibatalkan.');
  } catch (e) { message(e.message, 'err'); }
  $('cancelBtn').disabled = false;
};
$('anotherBtn').onclick = () => { show('done', false); show('opts', !!video); };
function saveHistory() { try { localStorage.setItem('softload-history', JSON.stringify(history)); } catch {} renderHistory(); }
function renderHistory() {
  const list = $('historyList'); list.replaceChildren(); $('clearHistory').disabled = !history.length;
  if (!history.length) { const p = document.createElement('p'); p.textContent = 'Belum ada berkas yang selesai diproses.'; list.append(p); }
  for (const item of history) {
    const row = document.createElement('div'); row.className = 'history-item';
    const title = document.createElement('p'); title.textContent = item.title;
    const meta = document.createElement('span'); meta.textContent = item.format + (item.format === 'MP4' ? ' / ' + item.quality + 'p' : '') + ' / ' + new Date(item.date).toLocaleString('id-ID');
    row.append(title, meta);
    if (item.expires * 1000 > Date.now()) {
      const a = document.createElement('a'); a.textContent = 'Simpan berkas'; a.href = fileURL(item.id); row.append(a);
    } else { const p = document.createElement('p'); p.textContent = 'Berkas kedaluwarsa. Proses tautannya kembali.'; row.append(p); }
    list.append(row);
  }
}
$('clearHistory').onclick = () => { history = []; saveHistory(); };
renderHistory();
api('health').then(() => { $('serviceNote').textContent = 'Layanan terhubung. Berkas disimpan sementara selama 1 jam.'; }).catch(e => { $('serviceNote').textContent = e.message; });

 
     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                